def fetch(pinned):
    api=apis.simple_note
    res=[]
    page=0
    while True:
        r=api.search_notes(access_token=sn_access['access_token'], query='dinner', pinned=pinned, page_index=page, page_limit=20, sort_by='-updated_at', dont_reorder_pinned=True)
        if not r:
            break
        res.extend(r)
        if len(r)<20:
            break
        page+=1
        if page>20: break
    return res

